# The agy engine's read-only check (A17): '' when nothing the review must not touch changed
# during the run, else the reason - the working tree (tracked or untracked files; the paths
# that changed), the brief, an artifact, or the task's handoffs (outside the tree
# fingerprint; the run's own NN-<prefix>-<slug>.* files excepted).
function Get-EngineTreeProblem {
    param($RevBefore, $RevAfter, [bool]$BriefChanged, [string[]]$ChangedArtifacts, [hashtable]$HandoffsBefore, [hashtable]$HandoffsAfter, [string[]]$OwnPrefixes, [string]$Engine)
    $cut = { param([string[]]$Names) $n = @($Names); $list = (@($n | Select-Object -First 5) -join ', '); if ($n.Count -gt 5) { $list += ', ...' }; "$($n.Count) file$(if ($n.Count -ne 1) { 's' }): $list" }
    $why = New-Object System.Collections.Generic.List[string]
    if ($RevBefore.tree_sha256 -ne $RevAfter.tree_sha256) {
        $paths = Get-ManifestChanges -Before $RevBefore.manifest -After $RevAfter.manifest
        $why.Add("the reviewer changed the working tree ($(& $cut $paths))")
    }
    $hand = Compare-DirectorySnapshot -Before $HandoffsBefore -After $HandoffsAfter -IgnorePrefixes $OwnPrefixes
    if ($hand.Count -gt 0) { $why.Add("the reviewer changed the task's handoffs ($(& $cut $hand))") }
    if ($BriefChanged) { $why.Add('the brief changed during the review') }
    if (@($ChangedArtifacts).Count -gt 0) { $why.Add("artifact(s) changed during the review: $(@($ChangedArtifacts) -join ', ')") }
    if ($why.Count -eq 0) { return '' }
    return (($why.ToArray() -join '; ') + " - $Engine's sandbox does not block writes")
}

